// servableStatic은 서빙을 허용할 정적 자산 경로인지 판단합니다.
//
// 예전에는 파일 하나하나를 손으로 적은 화이트리스트였습니다. 그래서 새 JS 모듈을
// 더하면서 목록에 넣는 것을 잊으면, 개발 중에는(디스크에서 직접 서빙) 멀쩡하다가
// 실제 배포에서만 404 가 되고 그 모듈을 import 하는 화면 전체가 죽었습니다.
//
// 임베드에 들어 있는 것만 서빙되므로 임의 파일 접근 위험은 이미 없습니다. 목록 대신
// 디렉터리로 허용하면 파일을 더할 때 자동으로 반영됩니다. pages/ 는 제외해 HTML 은
// 아래 pageRoutes 로만 닿게 합니다(직접 경로 접근 차단).
func servableStatic(path string) bool {
	switch path {
	case "/favicon.ico", "/favicon.png":
		return true
	}
	for _, prefix := range []string{"/js/", "/css/", "/img/"} {
		if strings.HasPrefix(path, prefix) {
			// 경로 조작 차단: 하위 디렉터리와 상위 참조를 허용하지 않습니다.
			rest := strings.TrimPrefix(path, prefix)
			return rest != "" && !strings.ContainsAny(rest, "/\\") && rest != "." && rest != ".."
		}
	}
	return false
}

func Handler() http.Handler {
	static, _ := fs.Sub(assets, ".")
	files := http.FileServer(http.FS(static))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		if path != "/" && strings.HasSuffix(path, "/") {
			path = strings.TrimSuffix(path, "/")
		}
		// /search?q=... 편의 경로 → 정식 워크스페이스 딥링크 /?sql=... 로 리다이렉트.
		// (q 를 sql 로 정규화하고 db·name·run 파라미터는 그대로 전달)
		if path == "/search" {
			in := r.URL.Query()
			out := url.Values{}
			if s := strings.TrimSpace(in.Get("sql")); s != "" {
				out.Set("sql", s)
			} else if s := strings.TrimSpace(in.Get("q")); s != "" {
				out.Set("sql", s)
			}
			for _, k := range []string{"db", "name", "run"} {
				if v := in.Get(k); v != "" {
					out.Set(k, v)
				}
			}
			target := "/"
			if enc := out.Encode(); enc != "" {
				target = "/?" + enc
			}
			http.Redirect(w, r, target, http.StatusFound)
			return
		}
		if pageName, ok := pageRoutes[path]; ok {
			page, err := assets.ReadFile(pageName)
			if err != nil {
				http.Error(w, "DartFly UI를 불러올 수 없습니다", http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			_, _ = w.Write(page)
			return
		}
		if servableStatic(r.URL.Path) {
			files.ServeHTTP(w, r)
			return
		}
		http.NotFound(w, r)
	})
}

