class Element {
  children = []; listeners = {}; className = ''; hidden = false; disabled = false; value = ''; content = '';
  classList = {
    add: (name) => { this.className += ` ${name}`; },
    remove: (name) => { this.className = this.className.split(' ').filter((c) => c !== name).join(' '); },
  };
  set textContent(value) { this.content = value; this.children = []; }
  get textContent() { return this.content + this.children.map((c) => c.textContent).join(''); }
  set innerHTML(value) { this.textContent = value; }
  get innerHTML() { return this.textContent; }
  append(...children) { this.children.push(...children); }
  replaceChildren(...children) { this.content = ''; this.children = children; }
  addEventListener(type, listener) { this.listeners[type] = listener; }
  querySelectorAll() { return this.children.filter((c) => c.className.includes(' active')); }
  // Dispatch even hidden/disabled actions to verify the handler's state guard too.
  fire(type = 'click') { return this.listeners[type]?.(); }
}
const detail = (id) => ({ id, db_seq: id + 10, db_name: `DB${id}`, sql: `SELECT ${id}`, row_count: 1, columns: [{ name: 'n', type: 'INT' }], rows: [{ n: id }] });
const tick = () => new Promise((resolve) => setImmediate(resolve));
async function page() {
  const elements = new Map();
  const el = (name) => {
    const selector = name.startsWith('#') ? name : `#saved-${name}`;
    if (!elements.has(selector)) elements.set(selector, new Element());
    return elements.get(selector);
  };
  const requests = [], copies = [], notices = [], storage = new Map();
  const window = { confirm: () => true, location: { href: '/saved' } };
  const context = vm.createContext({
    document: { querySelector: el, createElement: () => new Element() }, window,
    sessionStorage: { setItem: (key, value) => storage.set(key, value) },
    api: (url, options = {}) => new Promise((resolve, reject) => requests.push({ url, method: options.method || 'GET', resolve, reject })),
    initLayout: () => Promise.resolve(), fmtDate: () => '', highlightSQL: (sql) => sql,
    toast: (...args) => notices.push(args), copyText: (text) => copies.push(text),
    setTimeout, clearTimeout, tsvCell,
  });
  // Only replace imports; run the production initialization and event listeners unchanged.
  vm.runInContext(repoFile('internal/webui/js/saved.js').replace(/^import .*;\n/gm, ''), context);
  await tick();
  requests.shift().resolve({ items: [detail(1), detail(2)] });
  await tick();
  const select = (id) => el('list').children.find((c) => c.textContent.startsWith(`#${id} ·`)).fire();
  const request = (id, method = 'GET') => requests.findLast((r) => r.url.endsWith(`/${id}`) && r.method === method);
  const ready = async (id) => { select(id); request(id).resolve(detail(id)); await tick(); };
  const current = () => vm.runInContext('current', context);
  return { el, requests, copies, notices, storage, window, select, request, ready, current };
}
function assertReady(p, id) {
  assert.equal(p.current()?.id, id);
  assert.match(p.el('title').textContent, new RegExp(`결과 #${id} ·`));
  assert.equal(p.el('#saved-sql > code').innerHTML, `SELECT ${id}`);
  assert.equal(p.el('sql').hidden, false);
  assert.match(p.el('result').textContent, new RegExp(`${id}$`));
  assert.deepEqual(p.el('list').querySelectorAll().map((c) => c.children[0].textContent), [`#${id} · DB${id}`]);
  for (const name of ['tsv', 'open', 'delete']) assert.equal(p.el(name).hidden, false);
}
async function assertBlocked(p) {
  assert.equal(p.current(), null);
  assert.equal(p.el('sql').hidden, true);
  assert.equal(p.el('#saved-sql > code').innerHTML, '');
  for (const name of ['tsv', 'open', 'delete']) {
    assert.equal(p.el(name).hidden, true);
    await p.el(name).fire();
  }
  assert.equal(p.copies.length, 0);
  assert.equal(p.storage.size, 0);
  assert.equal(p.window.location.href, '/saved');
  assert.equal(p.requests.filter((r) => r.method === 'DELETE').length, 0);
}

