	case time.Time:
		return typed.Format(time.RFC3339Nano)
	case int64:
		if typed > maxExactJSInteger || typed < -maxExactJSInteger {
			return strconv.FormatInt(typed, 10)
		}
		return typed
	case uint64:
		if typed > maxExactJSInteger {
			return strconv.FormatUint(typed, 10)
		}
		return typed
	default:
		return typed
	}
}

